<?php require __DIR__.'/cms/library.php';$data=lash_data();$kind=($_GET['type']??'photos')==='videos'?'videos':'photos';$title=$kind==='photos'?'Image Gallery':'Video Gallery';?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="Official Lashirah <?=lash_escape($title)?>"><title><?=lash_escape($title)?> · Lashirah</title><style>*{box-sizing:border-box}body{margin:0;background:#081328;color:white;font-family:system-ui,-apple-system,sans-serif}header{padding:26px max(20px,calc((100vw - 1120px)/2));background:#101e37;border-bottom:1px solid #263a57}a{color:#e8bd6c}header a{text-decoration:none}main{max-width:1160px;margin:40px auto;padding:0 20px}h1{font-size:clamp(28px,5vw,48px);margin:0 0 12px}.tabs{display:flex;gap:12px;margin:25px 0}.tabs a{padding:12px 20px;border:1px solid #425671;border-radius:999px;text-decoration:none}.tabs .active{background:#d5b477;color:#101629}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(270px,1fr));gap:20px}.card{margin:0;background:#15243d;border:1px solid #314766;border-radius:15px;overflow:hidden}.card img{display:block;width:100%;aspect-ratio:16/10;object-fit:cover}.card figcaption{padding:15px}.video{width:100%;aspect-ratio:16/9;border:0;display:block}.empty{padding:32px;background:#15243d;border-radius:15px;color:#c8d5e8}</style></head><body><header><a href="/">← Lashirah / Official website</a></header><main><h1><?=lash_escape($title)?></h1><p>Explore Lashirah's journey, events and achievements.</p><nav class="tabs"><a class="<?=$kind==='photos'?'active':''?>" href="/gallery.php?type=photos">Image Gallery</a><a class="<?=$kind==='videos'?'active':''?>" href="/gallery.php?type=videos">Video Gallery</a></nav><?php if(!$data[$kind]): ?><div class="empty">New <?=strtolower(lash_escape($title))?> content will appear here soon.</div><?php else: ?><div class="grid"><?php foreach($data[$kind] as $item): ?><figure class="card"><?php if($kind==='photos'): ?><img loading="lazy" src="<?=lash_escape($item['url'])?>" alt="<?=lash_escape($item['caption'])?>"><figcaption><?=lash_escape($item['caption'])?></figcaption><?php else: ?><iframe class="video" loading="lazy" src="https://www.youtube-nocookie.com/embed/<?=lash_escape($item['youtube_id'])?>" title="<?=lash_escape($item['title'])?>" referrerpolicy="strict-origin-when-cross-origin" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe><figcaption><?=lash_escape($item['title'])?></figcaption><?php endif ?></figure><?php endforeach ?></div><?php endif ?></main></body></html>
